package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;
/** Weekly lecture reminders; Android background launch limits are reported, never hidden. */
public final class BlackboardSchedule extends android.content.BroadcastReceiver {
 static final String CHANNEL="nubi-blackboard-lecture";
 static long next(int weekday,int hour,int minute,long now){if(weekday<1||weekday>7||hour<0||hour>23||minute<0||minute>59)throw new IllegalArgumentException("Invalid lecture schedule");Calendar d=Calendar.getInstance();d.setTimeInMillis(now);d.set(Calendar.DAY_OF_WEEK,weekday);d.set(Calendar.HOUR_OF_DAY,hour);d.set(Calendar.MINUTE,minute);d.set(Calendar.SECOND,0);d.set(Calendar.MILLISECOND,0);if(d.getTimeInMillis()<=now)d.add(Calendar.DAY_OF_YEAR,7);return d.getTimeInMillis();}
 static PendingIntent alarm(Context c,String id){return PendingIntent.getBroadcast(c,id.hashCode(),new Intent(c,BlackboardSchedule.class).setAction("nubi.bb.lecture."+id).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void save(Context c,JSONObject row){String url=row.optString("url");if(!BlackboardDownloads.allowed(url)||!url.contains("/webapps/collab-ultra/tool/collabultra/lti/launch?course_id="))throw new IllegalArgumentException("검증한 강의의 Collaborate 주소가 필요해요.");String id=row.optString("id",UUID.randomUUID().toString());GoalStore.put(row,"id",id);long when=next(row.optInt("weekday"),row.optInt("hour"),row.optInt("minute"),System.currentTimeMillis());GoalStore.put(row,"nextAt",when);try(CampusFlowStore s=new CampusFlowStore(c)){s.save("bb_schedules",row);}((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,alarm(c,id));}
 static void remove(Context c,String id){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(alarm(c,id));try(CampusFlowStore s=new CampusFlowStore(c)){s.remove(id);}}
 public void onReceive(Context c,Intent intent){if(Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())){try(CampusFlowStore s=new CampusFlowStore(c)){for(JSONObject row:s.list("bb_schedules"))save(c,row);}return;}String id=intent.getStringExtra("id");JSONObject row;try(CampusFlowStore s=new CampusFlowStore(c)){row=s.get(id==null?"":id);}if(!row.has("id"))return;save(c,row);Intent open=new Intent(c,GoalAgentActivity.class).putExtra("goal_id",row.optString("goal_id")).putExtra("bb_launch_url",row.optString("url")).putExtra("bb_auto_join",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);android.app.Activity foreground=NubiApplication.foreground.get();if(foreground instanceof GoalAgentActivity&&!foreground.isFinishing()&&((GoalAgentActivity)foreground).runs.active()==null){GoalAgentActivity a=(GoalAgentActivity)foreground;new BlackboardTools(a.chat).show(row.optString("url"),true);return;}NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel(CHANNEL,"Blackboard 강의 접속",NotificationManager.IMPORTANCE_HIGH));PendingIntent tap=PendingIntent.getActivity(c,id.hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{manager.notify(id.hashCode(),new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(row.optString("title","Blackboard 강의 시간이에요")).setContentText("눌러서 보관된 세션으로 접속 · 백그라운드에서는 자동 화면 실행이 제한돼요.").setContentIntent(tap).setAutoCancel(true).build());}catch(SecurityException denied){c.getSharedPreferences("nubi_bb_preferences",0).edit().putString("schedule_error","알림 권한이 없어 강의 알림을 표시하지 못했어요.").apply();}}
}
